import java.io.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        int totalLines = Integer.parseInt(reader.readLine());
        String data = reader.readLine();
        String regex = "\\([\\w_]*\\)";
        String[] segments = data.split(regex);
        int maxLength = 0;
        for (String segment : segments) {
            maxLength = Math.max(maxLength, findMaxWordLength(segment));
        }
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(data);
        long insideCount = 0;
        while (matcher.find()) {
            String inside = extractContent(matcher.group());
            insideCount += Arrays.stream(inside.split("_"))
                                 .filter(s -> !s.isEmpty())
                                 .count();
        }
        writer.println(maxLength + " " + insideCount);
        writer.flush();
    }

    private static int findMaxWordLength(String s) {
        return Arrays.stream(s.split("_"))
                     .mapToInt(String::length)
                     .max()
                     .orElse(0);
    }

    private static String extractContent(String s) {
        return s.substring(1, s.length() - 1);
    }
}
