#include <iostream>
#include <string>
#include <regex>
#include <algorithm>
#include <sstream>

int findMaxWordLength(const std::string& s) {
    std::istringstream iss(s);
    std::string token;
    int maxLen = 0;
    while (std::getline(iss, token, '_')) {
        maxLen = std::max(maxLen, static_cast<int>(token.length()));
    }
    return maxLen;
}

std::string extractContent(const std::string& s) {
    return s.substr(1, s.length() - 2);
}

int main() {
    int totalLines;
    std::cin >> totalLines;
    std::cin.ignore(); // To consume the newline after the integer input
    std::string data;
    std::getline(std::cin, data);
    std::string regex_pattern = "\\([\\w_]*\\)";
    std::regex pattern(regex_pattern);
    std::sregex_iterator iter(data.begin(), data.end(), pattern);
    std::sregex_iterator end;
    int maxLength = 0;
    long long insideCount = 0;

    for (; iter != end; ++iter) {
        std::string inside = extractContent(iter->str());
        maxLength = std::max(maxLength, findMaxWordLength(inside));
        std::istringstream iss(inside);
        std::string s;
        while (std::getline(iss, s, '_')) {
            if (!s.empty()) {
                ++insideCount;
            }
        }
    }

    std::cout << maxLength << " " << insideCount << std::endl;
    return 0;
}
